static void testPerformanceAppend(size_t count) {
    ArrayList* list = ArrayListInit(sizeof(int), 1);
    assert(list != nullptr);

    double start = nowSeconds();

    for (size_t i = 0; i < count; i++) {
        int value = (int)i;
        arrayListAppend(list, &value);
    }

    double end = nowSeconds();

    assert(ArrayListGetLength(list) == (int)count);
    assert(ArrayListGetCapacity(list) >= count);

    printTiming("Performance - append", end - start);

    arrayListFree(list);
}

static void testPerformanceAt(size_t count) {
    ArrayList* list = ArrayListInit(sizeof(int), (unsigned int)count);
    assert(list != nullptr);

    for (size_t i = 0; i < count; i++) {
        int value = (int)i;
        arrayListAppend(list, &value);
    }

    volatile long long sum = 0;
    double start = nowSeconds();

    for (size_t i = 0; i < count; i++) {
        int* value = (int*)ArrayListAt(list, (int)i);
        assert(value != nullptr);
        sum += *value;
    }

    double end = nowSeconds();

    printTiming("Performance - at", end - start);

    if (sum == -1) {
        printf("Impossible sum: %lld\n", sum);
    }

    arrayListFree(list);
}

static void testPerformancePop(size_t count) {
    ArrayList* list = ArrayListInit(sizeof(int), (unsigned int)count);
    assert(list != nullptr);

    for (size_t i = 0; i < count; i++) {
        int value = (int)i;
        arrayListAppend(list, &value);
    }

    double start = nowSeconds();

    while (ArrayListGetLength(list) > 0) {
        arrayListPop(list);
    }

    double end = nowSeconds();

    assert(ArrayListGetLength(list) == 0);
    printTiming("Performance - pop", end - start);

    arrayListFree(list);
}

